--
-- Table structure for table `LeaderboardEvent`
--

DROP TABLE IF EXISTS `LeaderboardEvent`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `LeaderboardEvent` (
  `id` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `participantId` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `eventName` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `type` enum('PR_MERGED','ISSUE_COMPLETED','BONUS','PENALTY','MANUAL_ADJUSTMENT') COLLATE utf8mb4_unicode_ci NOT NULL,
  `pointsDelta` int NOT NULL,
  `prId` bigint DEFAULT NULL,
  `issueId` varchar(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  KEY `idx_lb_event_participant_time` (`participantId`,`createdAt`),
  KEY `idx_lb_event_event_time` (`eventName`,`createdAt`),
  KEY `idx_lb_event_participant_event` (`participantId`,`eventName`),
  CONSTRAINT `fk_lb_event_event` FOREIGN KEY (`eventName`) REFERENCES `Event` (`name`) ON DELETE CASCADE,
  CONSTRAINT `fk_lb_event_participant` FOREIGN KEY (`participantId`) REFERENCES `Participant` (`participantId`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

